{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C72", "C94", "C109", "C118"],
  "contradictory_card_ids": ["C31", "C03", "C08", "C09", "C11", "C13", "C17", "C28", "C37", "C51", "C52", "C04", "C12", "C27", "C01", "C36", "C22"],
  "prediction_basis_card_ids": ["C72", "C94", "C109", "C118"],
  "claims": [
    {
      "claim": "L3 oral exposure records for the related pyrimidine nucleoside uridine show that without the nucleoside phosphorylase inhibitor PSAU, oral uridine exposure is low (Cmax 15.7–23.6 µM; AUC 28.9–109 µmol·h·L−1 across 330–1320 mg/kg), whereas coadministration of PSAU 120 mg/kg with uridine 330 mg/kg raises Cmax to 107 µM and AUC to 256 µmol·h·L−1, demonstrating that first-pass metabolism can severely limit oral nucleoside bioavailability.",
      "card_ids": ["C72", "C94", "C109", "C118"]
    },
    {
      "claim": "The query is a 5-azacytosine 2'-deoxyriboside; the high-F L1/L2 cytidine analog contexts (lamivudine, zalcitabine) lack the 5-aza ring nitrogen present in the query, so their high-F outcomes are not directly transferable.",
      "card_ids": ["C31", "C03", "C08", "C09", "C11", "C13", "C17", "C28", "C37", "C51", "C52"]
    },
    {
      "claim": "No L3 record provides oral exposure data for the query itself; the most relevant mechanistic signal is the uridine/PSAU first-pass effect, which supports a low-F prediction for the query.",
      "card_ids": ["C72", "C94", "C109", "C118"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C72", "C94", "C109", "C118"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (decitabine).",
    "No card specifically addresses 5-azacytosine chemical stability or cytidine deaminase-mediated first-pass metabolism.",
    "L3 records are for other nucleosides (uridine, lamivudine, famciclovir, didanosine, zidovudine, levovirin, ribavirin), not the query.",
    "Transfer from uridine/PSAU is indirect; the metabolic enzyme and sugar moiety differ from the query.",
    "High-F L1/L2 contexts lack the 5-aza modification, limiting their transferability."
  ],
  "decision_summary": "Flipped to low: the query is a 5-azacytosine 2'-deoxyriboside. L3 oral exposure records for the related nucleoside uridine show that first-pass metabolism severely limits oral exposure unless a metabolism inhibitor is coadministered (C72 vs C94/C109/C118). This mechanistic evidence, together with the query's unfavorable passive absorption prior and the structural difference from high-F cytidine analogs, supports F < 20%; the high-F L1/L2 nucleoside outcomes are less transferable because they lack the 5-aza lability."
}

